 private FrameLayout container;private NavigationView sideNav;private androidx.drawerlayout.widget.DrawerLayout drawer;private MaterialToolbar toolbar;private TextInputEditText input;private TextInputLayout inputLayout;private TextView searchHelp,locationBadge,locationStatus;private String searchType="email",lastIdentifier="",countryCode="",countryName="Detecting region";private final ExecutorService executor=Executors.newSingleThreadExecutor();private final ArrayList<BreachResult> breaches=new ArrayList<>();private final ArrayList<PublicMatch> publicMatches=new ArrayList<>();
 @Override protected void onCreate(Bundle state){super.onCreate(state);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);WindowInsetsControllerCompat ic=WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView());ic.setAppearanceLightStatusBars(true);ic.setAppearanceLightNavigationBars(true);setContentView(R.layout.activity_main);View root=findViewById(R.id.rootLayout);ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{Insets b=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());v.setPadding(v.getPaddingLeft(),b.top,v.getPaddingRight(),b.bottom);return insets;});ViewCompat.requestApplyInsets(root);toolbar=findViewById(R.id.topAppBar);toolbar.setTitle("DeleteMe");drawer=findViewById(R.id.drawerLayout);sideNav=findViewById(R.id.sideNavigation);toolbar.setNavigationOnClickListener(v->drawer.openDrawer(Gravity.LEFT));sideNav.setNavigationItemSelectedListener(i->{int id=i.getItemId();if(id==R.id.nav_scan){showScan();}else if(id==R.id.nav_results){showResults();}else if(id==R.id.nav_settings){showSettings();}drawer.closeDrawer(Gravity.LEFT);return true;});container=findViewById(R.id.screenContainer);sideNav.setCheckedItem(R.id.nav_scan);showScan();}
 private void showScan(){sideNav.setCheckedItem(R.id.nav_scan);toolbar.setTitle("Scan");View v=getLayoutInflater().inflate(R.layout.screen_scan,container,false);container.removeAllViews();container.addView(v);input=v.findViewById(R.id.identifierInput);inputLayout=v.findViewById(R.id.identifierLayout);searchHelp=v.findViewById(R.id.searchHelp);locationBadge=v.findViewById(R.id.locationBadge);locationStatus=v.findViewById(R.id.locationStatus);Chip e=v.findViewById(R.id.typeEmail),m=v.findViewById(R.id.typeMobile),u=v.findViewById(R.id.typeUsername),n=v.findViewById(R.id.typeName);e.setOnClickListener(x->type("email"));m.setOnClickListener(x->type("mobile"));u.setOnClickListener(x->type("username"));n.setOnClickListener(x->type("name"));MaterialButton b=v.findViewById(R.id.findButton);b.setOnClickListener(x->scan(b));updateLocationUi();}
 private void type(String t){searchType=t;input.setText("");inputLayout.setError(null);if(t.equals("email")){inputLayout.setHint("Email address");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);searchHelp.setText("Checks XposedOrNot breach intelligence and shows the reported exposure details.");}else if(t.equals("mobile")){inputLayout.setHint("Mobile number");input.setInputType(InputType.TYPE_CLASS_PHONE);searchHelp.setText("Checks supported public sources. A removal route is not proof that your number was found.");}else if(t.equals("username")){inputLayout.setHint("Username / handle");input.setInputType(InputType.TYPE_CLASS_TEXT);searchHelp.setText("Checks public GitHub and GitLab profiles. Matches are possible matches, not identity proof.");}else{inputLayout.setHint("Full name");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS);searchHelp.setText("Checks public developer profiles. Name matches are possible matches, not identity proof.");}}
 private void scan(MaterialButton b){String v=input.getText()==null?"":input.getText().toString().trim();if(v.isEmpty()){inputLayout.setError("Enter something to search");return;}if(searchType.equals("email")&&!android.util.Patterns.EMAIL_ADDRESS.matcher(v).matches()){inputLayout.setError("Enter a valid email address");return;}if(searchType.equals("mobile")&&v.replaceAll("\\D","").length()<8){inputLayout.setError("Enter a valid mobile number");return;}if((searchType.equals("username")||searchType.equals("name"))&&v.length()<2){inputLayout.setError("Enter at least 2 characters");return;}lastIdentifier=v;inputLayout.setError(null);b.setEnabled(false);b.setText("Searching…");executor.execute(()->{try{breaches.clear();publicMatches.clear();if(searchType.equals("email"))loadEmail(v);else if(searchType.equals("username"))loadUsername(v);else if(searchType.equals("name"))loadName(v);else loadMobile(v);runOnUiThread(()->{b.setEnabled(true);b.setText("Find my data  →");showResults();});}catch(Exception e){runOnUiThread(()->{b.setEnabled(true);b.setText("Try again");Toast.makeText(this,"Search failed: "+e.getMessage(),Toast.LENGTH_LONG).show();});}});}
 private void loadEmail(String email)throws Exception{String q=URLEncoder.encode(email,"UTF-8");String s=get(XON+"check-email/"+q+"?details=true");JSONObject r=new JSONObject(s);JSONArray names=r.optJSONArray("breaches");if(names!=null&&names.length()>0&&names.opt(0) instanceof JSONArray){JSONArray a=names.optJSONArray(0);for(int i=0;i<a.length();i++)addBreachName(a.optString(i));}else if(names!=null){for(int i=0;i<names.length();i++)addBreachName(names.optString(i));}if(breaches.isEmpty())return;try{JSONObject analytics=new JSONObject(get(XON+"breach-analytics?email="+q));JSONObject eb=analytics.optJSONObject("ExposedBreaches");JSONArray d=eb==null?null:eb.optJSONArray("breaches_details");if(d!=null)for(int i=0;i<d.length();i++){JSONObject x=d.optJSONObject(i);if(x==null)continue;BreachResult b=findBreach(x.optString("breach",""));if(b==null){b=new BreachResult(x.optString("breach","Unknown source"),x.optString("domain",""),x.optString("xposed_date",""),x.optString("xposed_data",""),x.optLong("xposed_records",0),x.optString("details",""),x.optString("references",""),x.optString("password_risk",""));breaches.add(b);}else{b.domain=x.optString("domain",b.domain);b.date=x.optString("xposed_date",b.date);b.data=x.optString("xposed_data",b.data);b.records=x.optLong("xposed_records",b.records);b.description=x.optString("details",b.description);b.references=x.optString("references",b.references);b.passwordRisk=x.optString("password_risk",b.passwordRisk);}}}catch(Exception ignored){for(BreachResult b:breaches)if(b.description.isEmpty())b.description="Breach was reported by XposedOrNot. Detailed metadata is temporarily unavailable.";}}
 private void addBreachName(String name){if(name==null||name.trim().isEmpty())return;if(findBreach(name)==null)breaches.add(new BreachResult(name,"","","",0,"","",""));}
 private BreachResult findBreach(String name){for(BreachResult b:breaches)if(b.name.equalsIgnoreCase(name))return b;return null;}
 private void loadUsername(String u)throws Exception{String q=URLEncoder.encode(u,"UTF-8");if(code(GH+"users/"+q)==200)publicMatches.add(new PublicMatch("GitHub","Public profile","https://github.com/"+u,"Public username match."));String gl=GL+"users?username="+q;if(code(gl)==200){JSONArray a=new JSONArray(get(gl));if(a.length()>0)publicMatches.add(new PublicMatch("GitLab","Public profile","https://gitlab.com/"+u,"Public username match."));}}
 private void loadName(String n)throws Exception{JSONObject o=new JSONObject(get(GH+"search/users?q="+URLEncoder.encode(n,"UTF-8")+"&per_page=10"));JSONArray a=o.optJSONArray("items");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)publicMatches.add(new PublicMatch("GitHub","Possible public profile","https://github.com/"+x.optString("login"),"Returned by GitHub name search."));}}
