 private void showResults(){sideNav.setCheckedItem(R.id.nav_results);toolbar.setTitle("Results");container.removeAllViews();ScrollView s=new ScrollView(this);s.setBackgroundColor(BG);LinearLayout r=column(20,18,20,30);s.addView(r);container.addView(s);label(r,"SCAN RESULTS");int total=breaches.size()+publicMatches.size();r.addView(text(total+" result"+(total==1?"":"s")+" found",30,INK,true),margin(0,7,0,5));r.addView(text(breaches.size()>0?"Review the exact source, date and exposed data before deciding whether to remove anything.":"Review each public match before deciding whether to request removal.",15,MUTED,false),margin(0,0,0,15));LinearLayout st=row();r.addView(st,margin(0,0,0,12));st.addView(stat("CONFIRMED EXPOSURES",String.valueOf(breaches.size()),RED_BG,RED),weight());addSpace(st,10);st.addView(stat("PUBLIC MATCHES",String.valueOf(publicMatches.size()),BLUE_BG,BLUE),weight());MaterialButton dir=primaryButton("Browse regional removal options");dir.setOnClickListener(v->showDirectory(lastIdentifier));r.addView(dir,margin(0,2,0,16));for(BreachResult b:breaches)addBreach(r,b);for(PublicMatch p:publicMatches)addPublic(r,p);if(total==0)addEmpty(r);}
 private void addBreach(LinearLayout r,BreachResult b){MaterialCardView c=card(WHITE,RED);LinearLayout x=column(17,17,17,17);c.addView(x);r.addView(c,margin(0,0,0,12));x.addView(badge("CONFIRMED EXPOSURE",RED),margin(0,0,0,10));x.addView(text(b.name,21,INK,true));if(!b.domain.isEmpty())x.addView(text(b.domain,13,MUTED,false),margin(0,2,0,10));if(!b.date.isEmpty())x.addView(meta("Breach date",b.date),margin(0,0,0,8));if(b.records>0)x.addView(meta("Records affected",format(b.records)),margin(0,0,0,8));if(!b.data.isEmpty()){x.addView(text("DATA EXPOSED",11,MUTED,true),margin(0,3,0,5));x.addView(chips(b.data),margin(0,0,0,10));}if(!b.description.isEmpty())x.addView(text(b.description,13,MUTED,false),margin(0,0,0,9));if(!b.passwordRisk.isEmpty())x.addView(text("PASSWORD RISK  ·  "+b.passwordRisk,12,b.passwordRisk.toLowerCase().contains("plain")?RED:ORANGE,true),margin(0,0,0,8));LinearLayout a=row();x.addView(a);MaterialButton review=primaryButton("Review removal");review.setOnClickListener(v->showRemovalReview(b));a.addView(review,weight());addSpace(a,8);MaterialButton keep=secondaryButton("Keep");keep.setOnClickListener(v->c.setVisibility(View.GONE));a.addView(keep,weight());}
