 private void showProviderDecision(LinearLayout r,String provider,String domain){MaterialCardView c=card(WHITE,PRIMARY);LinearLayout x=column(17,17,17,17);c.addView(x);r.addView(c,margin(0,0,0,12));x.addView(text("What will removal do?",19,INK,true));x.addView(text("Removal asks the provider to delete, hide or unlist the data it controls. It cannot erase copies already republished elsewhere.",13,MUTED,false),margin(0,5,0,12));x.addView(text("AUTOMATION STATUS",11,MUTED,true));x.addView(text("Manual route required",15,ORANGE,true),margin(0,3,0,4));x.addView(text("DeleteMe does not pretend a browser link is an API. If an automated provider integration is added later, this card will show it explicitly.",13,MUTED,false));MaterialButton open=primaryButton("Open official removal route");String route=providerRoute(provider);open.setOnClickListener(v->{if(route.isEmpty())Toast.makeText(this,"No verified provider removal route is configured yet.",Toast.LENGTH_LONG).show();else open(route);});x.addView(open,margin(0,12,0,0));x.addView(text("Manual guide\n1. Open the verified provider route.\n2. Confirm the profile/data belongs to you.\n3. Request deletion, hiding or unlisting.\n4. Complete only the verification the provider requires.\n5. Return and record the request.",13,INK,false),margin(0,12,0,8));}
 private String providerRoute(String provider){for(String[] a:INDIA)if(a[0].equalsIgnoreCase(provider))return a[2];return "";}
