 private void showDirectory(String context){sideNav.setCheckedItem(R.id.nav_results);toolbar.setTitle("Removal Directory");ScrollView s=new ScrollView(this);s.setBackgroundColor(BG);LinearLayout r=column(20,18,20,30);s.addView(r);container.removeAllViews();container.addView(s);label(r,"REGIONAL REMOVAL");r.addView(text("Removal routes for "+countryName,28,INK,true),margin(0,7,0,4));r.addView(text("Location is used to choose relevant privacy/removal sources. A directory listing never means your data was found there.",14,MUTED,false),margin(0,0,0,15));if(!context.isEmpty()){MaterialCardView c=card(PRIMARY_BG,PRIMARY);LinearLayout x=column(15,15,15,15);c.addView(x);r.addView(c,margin(0,0,0,15));x.addView(text("YOU ARE REVIEWING",11,PRIMARY,true));x.addView(text(context,18,INK,true),margin(0,4,0,0));x.addView(text("Choose a provider below only if you actually use it.",13,MUTED,false),margin(0,4,0,0));}if("IN".equalsIgnoreCase(countryCode)){label(r,"INDIA SOURCES");for(String[] a:INDIA)if(a[4].equals("any")||matches(a[4],searchType))addRoute(r,a[0],a[1],a[2],a[3],ORANGE_BG,ORANGE);}else{label(r,"GLOBAL SOURCES");r.addView(text("No country-specific removal catalog is configured for "+countryName+" yet. Global broker routes are still available below.",13,MUTED,false),margin(0,0,0,10));}label(r,"GLOBAL BROKER REGISTRY");executor.execute(()->{try{JSONArray a=brokerArray();runOnUiThread(()->{for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String n=first(o,"company","name","broker"),u=first(o,"optOutUrl","opt_out_url","optout_url","opt_out","url");if(!n.isEmpty()&&!u.isEmpty())addRoute(r,n,"Data broker",u,"Official route. Not a confirmed finding.",WHITE,MUTED);}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Global directory unavailable.",Toast.LENGTH_LONG).show());}});}
