 private void requestLocationIfNeeded(){if(Build.VERSION.SDK_INT<23){detectLocation();return;}if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED||ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){detectLocation();return;}locationBadge.setText("Allow location");locationStatus.setText("Precise location is used only to choose relevant regional removal sources.");ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},LOCATION_REQUEST);}
 @Override public void onRequestPermissionsResult(int requestCode,@NonNull String[] permissions,@NonNull int[] results){super.onRequestPermissionsResult(requestCode,permissions,results);if(requestCode==LOCATION_REQUEST){boolean ok=false;for(int x:results)if(x==PackageManager.PERMISSION_GRANTED)ok=true;if(ok)detectLocation();else{countryName="Global";countryCode="";updateLocationUi();locationStatus.setText("Location permission was declined. Global sources remain available; regional routes will not be tailored.");}}}
 private void detectLocation(){executor.execute(()->{String cc="",cn="Global";try{LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);Location best=null;if(ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED||ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){for(String p:new String[]{LocationManager.NETWORK_PROVIDER,LocationManager.GPS_PROVIDER}){Location l=lm.getLastKnownLocation(p);if(l!=null&&(best==null||l.getTime()>best.getTime()))best=l;}}if(best!=null){Geocoder g=new Geocoder(this,Locale.getDefault());List<Address> a=g.getFromLocation(best.getLatitude(),best.getLongitude(),1);if(a!=null&&!a.isEmpty()){Address ad=a.get(0);cc=ad.getCountryCode()==null?"":ad.getCountryCode();cn=ad.getCountryName()==null?"Global":ad.getCountryName();}}}catch(Exception ignored){}String fcc=cc,fcn=cn;runOnUiThread(()->{countryCode=fcc;countryName=fcn;updateLocationUi();});});}
 private void updateLocationUi(){if(locationBadge==null||locationStatus==null)return;if(countryName.equals("Detecting region")){locationBadge.setText("Detecting region");locationStatus.setText("Location is used only to select relevant removal sources.");return;}if("IN".equalsIgnoreCase(countryCode)){locationBadge.setText("India");locationStatus.setText("India-specific privacy and removal routes will be prioritized.");}else{locationBadge.setText(countryName);locationStatus.setText("Regional sources will be selected when a verified catalog is available.");}}
 private void addEmpty(LinearLayout r){MaterialCardView c=card(GREEN_BG,GREEN);LinearLayout x=column(20,24,20,24);c.addView(x);r.addView(c,margin(0,0,0,10));TextView q=text("✓",36,GREEN,true);q.setGravity(Gravity.CENTER);x.addView(q);TextView h=text("No confirmed exposure found",19,INK,true);h.setGravity(Gravity.CENTER);x.addView(h,margin(0,6,0,4));TextView d=text("The checked source did not return a matching exposure. Removal options are separate from confirmed findings.",13,MUTED,false);d.setGravity(Gravity.CENTER);x.addView(d);}
 private boolean matches(String a,String b){return a.equals("any")||a.equals(b)||a.equals("phone")&&b.equals("mobile")||a.equals("profile")&&(b.equals("username")||b.equals("name"));}
 private void showSettings(){sideNav.setCheckedItem(R.id.nav_settings);toolbar.setTitle("Settings");View v=getLayoutInflater().inflate(R.layout.screen_settings,container,false);container.removeAllViews();container.addView(v);SwitchMaterial regional=v.findViewById(R.id.settingRegionalSearch);regional.setOnCheckedChangeListener((button,checked)->{if(checked)Toast.makeText(this,"Regional removal sources enabled.",Toast.LENGTH_SHORT).show();else Toast.makeText(this,"Regional source prioritization disabled.",Toast.LENGTH_SHORT).show();});TextView status=v.findViewById(R.id.settingLocationStatus);MaterialButton location=v.findViewById(R.id.settingLocationButton);if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){status.setText("Precise location permission is enabled for regional source selection.");location.setText("Location permission enabled");}else if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED){status.setText("Location permission is enabled. Precise location is preferred for regional search.");location.setText("Request precise location");}location.setOnClickListener(x->{requestLocationIfNeeded();if(Build.VERSION.SDK_INT>=23&&ActivityCompat.shouldShowRequestPermissionRationale(this,Manifest.permission.ACCESS_FINE_LOCATION))Toast.makeText(this,"Enable precise location in Android settings for the most accurate regional results.",Toast.LENGTH_LONG).show();});}
